import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { API } from "../api/api";
import Navbar from "../components/Navbar";

export default function SurveyPage() {
  const { id } = useParams();

  const [survey, setSurvey] = useState(null);
  const [answers, setAnswers] = useState([]);

  useEffect(() => {
    API.get(`/surveys/${id}`).then(res => setSurvey(res.data));
  }, [id]);

  const selectOption = (qIndex, optIndex) => {
    setAnswers(prev => {
      const updated = [...prev];
      const existing = updated.find(a => a.questionIndex === qIndex);

      if (existing) {
        existing.selectedOption = optIndex;
      } else {
        updated.push({ questionIndex: qIndex, selectedOption: optIndex });
      }

      return updated;
    });
  };

  const submitSurvey = async () => {
    if (answers.length !== survey.questions.length) {
      alert("Answer all questions 😤");
      return;
    }

    try {
      await API.post("/responses/survey", {
        surveyId: survey._id,
        answers
      });

      alert("Submitted successfully 🎉");
    } catch (err) {
      alert(err.response?.data?.msg || "Error");
    }
  };

  if (!survey) return <div className="loading">Loading...</div>;

  return (
    <>
      <Navbar />

      <div className="survey-page">
        <h2>{survey.title} 📝</h2>

        {survey.questions.map((q, qIndex) => (
          <div className="card" key={qIndex}>
            <h4>{q.questionText}</h4>

            {q.options.map((opt, optIndex) => {
              const selected = answers.find(
                a =>
                  a.questionIndex === qIndex &&
                  a.selectedOption === optIndex
              );

              return (
                <div
                  key={optIndex}
                  className={`option ${selected ? "active" : ""}`}
                  onClick={() => selectOption(qIndex, optIndex)}
                >
                  {opt.text}
                </div>
              );
            })}
          </div>
        ))}

        <button className="submit-btn" onClick={submitSurvey}>
          Submit 🚀
        </button>
      </div>

      <style>{`
        .survey-page {
          min-height:100vh;
          padding:40px;
          background:#0b1220;
          color:white;
        }

        .card {
          background:#1f2937;
          padding:20px;
          border-radius:12px;
          margin:20px auto;
          width:60%;
        }

        .option {
          padding:10px;
          margin-top:10px;
          background:#374151;
          border-radius:8px;
          cursor:pointer;
        }

        .option:hover {
          background:#4b5563;
        }

        .active {
          background:#22c55e !important;
        }

        .submit-btn {
          display:block;
          margin:30px auto;
          padding:12px 25px;
          background:#3b82f6;
          border:none;
          border-radius:10px;
          color:white;
          cursor:pointer;
        }

        .loading{
          height:100vh;
          display:flex;
          align-items:center;
          justify-content:center;
          color:white;
          background:#0b1220;
        }
      `}</style>
    </>
  );
}
